import { Cell } from "@ton/core/src/boc/Cell";
import { SendMode } from "@ton/core/src/types/SendMode";
import { TupleReader } from "@ton/core/src/tuple/reader";
import { TupleItem } from "@ton/core/src/tuple/tuple";
import { Maybe } from "@ton/core/src/utils/maybe";
import { ContractState } from "@ton/core/src/contract/ContractState";
import { Sender } from '@ton/core/src/contract/Sender';
import { Contract } from '@ton/core/src/contract/Contract';
import { Address } from "@ton/core/src/address/Address";
import { Transaction } from "@ton/core/src/types/Transaction";
import { OpenedContract } from "@ton/core/src/contract/openContract";

export type ContractGetMethodResult = {
    stack: TupleReader;
    gasUsed?: Maybe<bigint>;
    logs?: Maybe<string>;
}

export interface ContractProvider {
    getState(): Promise<ContractState>;
    get(name: string, args: TupleItem[]): Promise<ContractGetMethodResult>;
    external(message: Cell): Promise<void>;
    internal(via: Sender, args: { value: bigint | string, bounce?: Maybe<boolean>, sendMode?: SendMode, body?: Maybe<Cell | string> }): Promise<void>;
    open<T extends Contract>(contract: T): OpenedContract<T>;
    getTransactions(address: Address, lt: bigint, hash: Buffer, limit?: number): Promise<Transaction[]>;
}
